(* CLOCK_INPUT = "100000000" *) (* CLOCK_REF = "11500" *) (* STOPCOUNTER = "4347" *) 
module ref_clock
   (in_clock,
    nreset,
    out_clock_ref);
  (* dont_touch = "true" *) input in_clock;
  (* dont_touch = "true" *) input nreset;
  (* dont_touch = "true" *) output out_clock_ref;

  (* DONT_TOUCH *) wire done;
  (* DONT_TOUCH *) wire enab_ref_clock;
  (* DONT_TOUCH *) wire in_clock;
  (* DONT_TOUCH *) wire nreset;
  (* DONT_TOUCH *) wire out_clock_ref;
  wire out_clock_ref_i_1_n_2;
  (* DONT_TOUCH *) wire out_clock_ref_next;
  wire [12:0]NLW_counter_base_counter1_UNCONNECTED;

  (* DONT_TOUCH *) 
  (* MOD = "4347" *) 
  counter counter_base
       (.clock(in_clock),
        .counter1(NLW_counter_base_counter1_UNCONNECTED[12:0]),
        .counting_done(done),
        .ena(enab_ref_clock),
        .nreset(nreset));
  LUT1 #(
    .INIT(2'h2)) 
    i_2_0
       (.I0(1'b1),
        .O(enab_ref_clock));
  LUT1 #(
    .INIT(2'h1)) 
    out_clock_ref_i_1
       (.I0(nreset),
        .O(out_clock_ref_i_1_n_2));
  LUT1 #(
    .INIT(2'h1)) 
    out_clock_ref_next_inferred_i_1
       (.I0(out_clock_ref),
        .O(out_clock_ref_next));
  (* DONT_TOUCH *) 
  (* KEEP = "yes" *) 
  FDCE #(
    .INIT(1'b0)) 
    out_clock_ref_reg
       (.C(done),
        .CE(1'b1),
        .CLR(out_clock_ref_i_1_n_2),
        .D(out_clock_ref_next),
        .Q(out_clock_ref));
endmodule

